export const FREE_PLAN = "Grátis";
export const BASIC_PLAN = "Plano Básico";
export const PRO_PLAN = "Plano Pro";

export const PLANS = {
  [FREE_PLAN]: {
    price: 0, maxActiveFlags: 1,
    shapes: ["rectangle", "pill", "outline"],
    advancedStyle: false, animations: false, scheduling: false, customIcon: false,
  },
  [BASIC_PLAN]: {
    price: 5, maxActiveFlags: 10, shapes: "all",
    advancedStyle: true, animations: false, scheduling: false, customIcon: false,
  },
  [PRO_PLAN]: {
    price: 12, maxActiveFlags: Infinity, shapes: "all",
    advancedStyle: true, animations: true, scheduling: true, customIcon: true,
  },
};

/** Menor plano que suporta uma flag (usado no editor e no servidor). */
export function requiredPlanFor(flag) {
  const shape = normalizeShape(flag.template);
  const style = normalizeStyle(flag.style);
  if (style.animation !== "none" || flag.startsAt || flag.endsAt || flag.iconImageUrl) {
    return PRO_PLAN;
  }
  if (!PLANS[FREE_PLAN].shapes.includes(shape) || isAdvancedStyle(style)) {
    return BASIC_PLAN;
  }
  return FREE_PLAN;
}

export async function action({ request }) {
  const { session, admin, billing } = await authenticate.admin(request);
  const { data, errors } = parseFlagForm(await request.formData());

  if (Object.keys(errors).length) {
    return json({ errors }, { status: 422 });
  }

  const { planName } = await getCurrentPlan({ admin, session, billing });
  const planError = await checkPlanLimits(session.shop, data, planName);
  if (planError) {
    return json({ formError: planError }, { status: 403 });
  }

  await createFlag(session.shop, data);
  // grava a nova versão no metafield que o storefront lê
  await syncFlagsToMetafield(admin, session.shop);

  return redirect("/app/flags?toast=created");
}

/** Verifica se a flag cabe no plano atual. Retorna mensagem de erro ou null. */
export async function checkPlanLimits(shop, data, planName, { excludeId } = {}) {
  const required = requiredPlanFor(data);
  if (!planCovers(planName, required)) {
    return `Algumas opções escolhidas exigem o ${required}. Faça upgrade ou remova essas opções.`;
  }
  if (data.active) {
    const max = PLANS[planName]?.maxActiveFlags ?? 1;
    const active = await countActiveFlags(shop, { excludeId });
    if (active >= max) {
      return `Seu plano permite ${max} flags ativas. Desative outra flag ou faça upgrade.`;
    }
  }
  return null;
}

export async function updateFlag(id, shop, data) {
  // updateMany com filtro por shop: impede que uma loja altere flag de outra
  const { count } = await prisma.flag.updateMany({
    where: { id, shop },
    data: { ...data, shop },
  });
  return count > 0;
}

/**
 * O app embed está ligado no tema publicado? Lê config/settings_data.json.
 * Requer read_themes. Retorna true | false, ou null se não der para saber.
 */
export async function isAppEmbedEnabled(admin) {
  const response = await admin.graphql(`#graphql
    query MainThemeSettings {
      themes(first: 1, roles: [MAIN]) {
        nodes {
          files(filenames: ["config/settings_data.json"]) {
            nodes { body { ... on OnlineStoreThemeFileBodyText { content } } }
          }
        }
      }
    }`);
  const result = await response.json();
  const content = result.data?.themes?.nodes?.[0]?.files?.nodes?.[0]?.body?.content;
  if (!content) return null;

  // o arquivo pode começar com um comentário /* ... */ gerado pela Shopify
  const settings = JSON.parse(content.replace(/^\s*\/\*[\s\S]*?\*\//, ""));
  // "current" pode ser o objeto de configurações ou o nome de um preset
  const current =
    typeof settings?.current === "string" ? settings?.presets?.[settings.current] : settings?.current;
  return Object.values(current?.blocks ?? {}).some(
    (block) =>
      typeof block?.type === "string" &&
      block.type.includes("/blocks/product-flag/") &&
      block.disabled !== true,
  );
}

